public static void solve(FastScanner sc, FastPrintStream pw) throws Exception {
    int t = sc.nextInt();
    for (int times = 0; times < t; times++) {
        long n = sc.nextLong();
        long m = sc.nextLong();
        long k = sc.nextLong();
        int re[] = new int[] { 6, 2, 4, 8 };

        long divisor = (1L << m) - (1L << k);
        if (divisor == 0) {
            pw.println("undefined");
            continue;
        }

        long remainder = (1L << n) % divisor;
        int lastDigit = (int) (remainder % 10);
        pw.println(lastDigit);
    }
}
